             + ", ".join(failed) + ")")
        return 1
    emit(f"SELFTEST: PASS ({passed} cases)")
    return 0


# ----------------------------------------------------------------------- cli


def _sigterm(_signum, _frame):
    raise SystemExit(2)


def main(argv):
    if argv and argv[0] == "--selftest":
        if len(argv) != 1:
            return usage_failure("--selftest takes no further arguments")
        try:
            return selftest()
        except RuntimeError as exc:  # ScratchRootUnusable is a RuntimeError
            try:
                print(f"registry-check: could-not-evaluate: {exc}", file=sys.stderr)
                sys.stderr.flush()
            except (OSError, ValueError):
                pass
            return 2

    root = default_root()
    rev = None
    registry = None
    only = None
    tags = []
    as_json = False

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg in ("-h", "--help"):
            sys.stdout.write(__doc__)
            return 0
        if arg == "--json":
            as_json = True
            i += 1
            continue
        if arg in ("--root", "--rev", "--registry", "--only", "--tag"):
            if i + 1 >= len(argv):
                return usage_failure(f"{arg} requires a value")
            value = argv[i + 1]
            if arg == "--root":
                root = value
            elif arg == "--rev":
                rev = value
            elif arg == "--registry":
                registry = value
            elif arg == "--only":
                only = value
            else:
                tags.append(value)
            i += 2
            continue
        return usage_failure(f"unknown argument {arg!r}")

    signal.signal(signal.SIGTERM, _sigterm)

    if registry is not None:
        registry = os.path.abspath(registry)

    live = rev is None
    root_requested = root
    rev_resolved = None
    fleet_root = None
    if not os.path.isdir(root_requested):
        report = {
            "schema": REPORT_SCHEMA,
            "root": root_requested,
            "rev": rev,
            "error": f"root_unavailable: {root_requested}",
        }
        if as_json:
            emit(json.dumps(report, indent=2, sort_keys=True))
        else:
            emit(f"REGISTRY_CHECK: could-not-evaluate (root_unavailable: "
                 f"{root_requested})")
        return 2

    work = None
    if rev is not None:
        sha, error = resolve_rev(root_requested, rev)
        if error:
            report = {
                "schema": REPORT_SCHEMA,
                "root": root_requested,
                "rev": rev,
                "error": error,
            }
            if as_json:
                emit(json.dumps(report, indent=2, sort_keys=True))
            else:
                emit(f"REGISTRY_CHECK: could-not-evaluate ({error})")
            return 2
        rev_resolved = sha
        fleet_root = os.path.dirname(os.path.realpath(root_requested))
        try:
            work, root = clone_lane_at_rev(root_requested, rev, sha)
        except ScratchRootUnusable as exc:
            # The class, not a verdict: one stderr line with the frozen grammar and
            # exit 2. Under --json the machine report is still emitted (it is what
            # the docstring promises), carrying the refusal as its error field; a
            # stream that refuses either write must not change the class
            # (round 55, wave-2 F1/F2).
            report = {"schema": REPORT_SCHEMA, "root": root_requested, "rev": rev,
                      "error": f"could-not-evaluate: {exc}"}
            try:
                if as_json:
                    emit(json.dumps(report, indent=2, sort_keys=True))
                print(f"registry-check: could-not-evaluate: {exc}", file=sys.stderr)
                sys.stderr.flush()
            except (OSError, ValueError):
                pass
            return 2
        except RuntimeError as exc:
            report = {
                "schema": REPORT_SCHEMA,
                "root": root_requested,
                "rev": rev,
                "rev_resolved": sha,
                "error": str(exc),
            }
            if as_json:
                emit(json.dumps(report, indent=2, sort_keys=True))
            else:
                emit(f"REGISTRY_CHECK: could-not-evaluate ({exc})")
            return 2
        if registry is None:
            registry = os.path.join(root, "tools", "registry.json")
    else:
        root = os.path.abspath(root_requested)
        if registry is None:
            registry = os.path.join(root, "tools", "registry.json")

    try:
        if live:
            emit_err(
                "registry-check: warning: live --root mode runs rows in the "
                "lane; rows may write into the root (use --rev to grade a "
                "throwaway clone)"
            )
        code, report = evaluate(
            root, registry, only, tags, rev, rev_resolved, fleet_root, live
        )
    finally:
        if work is not None:
            shutil.rmtree(work, ignore_errors=True)

    report["exit"] = code
    if as_json:
        emit(json.dumps(report, indent=2, sort_keys=True))
        print_human(report, stream=sys.stderr)
    else:
        print_human(report, stream=sys.stdout)
    return code


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
